'use strict';
const $=s=>document.querySelector(s);
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const SCOOTERS=[
{id:'024',battery:86,range:28,walk:2,place:'Friedrichstraße · Mitte',x:558,y:462,tags:'mitte friedrichstraße friedrichstrasse unter den linden'},
{id:'018',battery:72,range:22,walk:4,place:'Brandenburger Tor · Mitte',x:408,y:565,tags:'brandenburger tor pariser platz mitte'},
{id:'031',battery:94,range:31,walk:6,place:'Reichstag · Tiergarten',x:372,y:465,tags:'reichstag tiergarten bundestag'},
{id:'042',battery:68,range:21,walk:8,place:'Hauptbahnhof · Moabit',x:286,y:331,tags:'hauptbahnhof moabit invalidenstraße'},
{id:'009',battery:81,range:26,walk:9,place:'Oranienburger Straße · Mitte',x:666,y:295,tags:'oranienburger straße strasse mitte'},
{id:'056',battery:58,range:18,walk:11,place:'Museumsinsel · Mitte',x:793,y:421,tags:'museumsinsel mitte berliner dom'},
{id:'063',battery:90,range:29,walk:13,place:'Potsdamer Platz · Tiergarten',x:398,y:769,tags:'potsdamer platz tiergarten'},
{id:'027',battery:77,range:24,walk:16,place:'Checkpoint Charlie · Kreuzberg',x:660,y:771,tags:'checkpoint charlie kreuzberg kochstraße'}];
const COORDS={'024':[52.5213,13.3883],'018':[52.5165,13.3781],'031':[52.5198,13.3763],'042':[52.5247,13.3695],'009':[52.5254,13.3932],'056':[52.5209,13.4004],'063':[52.5091,13.3765],'027':[52.5078,13.3908]};
const USER_LOCATION=[52.5185,13.3880];
let cityMap,markerLayer,routeLayer;
const STORAGE='escooter-berlin-demo-v1';
let state={view:'find',selected:'024',query:'',near:true,high:false,active:null,history:[],zoom:1,panX:0,panY:0,mobileMap:false};
let storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved){if(Array.isArray(saved.history))state.history=saved.history.filter(r=>r&&SCOOTERS.some(s=>s.id===r.scooterId)&&Number.isFinite(r.ended)&&Number.isFinite(r.total)&&Number.isFinite(r.duration)).slice(0,100);if(saved.active&&SCOOTERS.some(s=>s.id===saved.active.scooterId)&&['reserved','riding'].includes(saved.active.status)&&Number.isFinite(saved.active.created)&&Number.isFinite(saved.active.expires)&&(saved.active.status!=='riding'||Number.isFinite(saved.active.started)))state.active=saved.active;}}catch{storageAvailable=false;}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({active:state.active,history:state.history}));}catch{if(storageAvailable)toast('Deine Demo-Daten können hier nicht dauerhaft gespeichert werden.');storageAvailable=false;}}
function normalize(value){return value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ß/g,'ss').trim();}
function filtered(){const q=normalize(state.query);return SCOOTERS.filter(s=>(!state.high||s.battery>=80)&&(!q||normalize(`${s.id} scooter ${s.place} ${s.tags} berlin`).includes(q))).sort(state.near?(a,b)=>a.walk-b.walk:(a,b)=>b.battery-a.battery);}
function money(n){return new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n);}
function time(ms){const sec=Math.max(0,Math.floor(ms/1000));return `${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`;}
function scooter(id=state.selected){return SCOOTERS.find(s=>s.id===id);}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function renderList(){const list=filtered();if(!list.some(s=>s.id===state.selected))state.selected=list[0]?.id||null;
$('#scooter-list').innerHTML=list.length?list.map(s=>`<article class="scooter-card ${s.id===state.selected?'selected':''}" data-card="${s.id}"><img class="product-image" src="assets/scooter.webp" alt="Schwarzer E-Scooter mit grünem Lenkerrohr" width="150" height="225" data-select="${s.id}"><div class="card-details"><button class="card-title" data-select="${s.id}" aria-label="Scooter ${s.id} auf der Karte auswählen" aria-pressed="${s.id===state.selected}">Scooter ${s.id}</button><div class="card-meta">${icon('walk')}<span>ca. ${s.walk} Min. zu Fuß</span></div><div class="card-meta battery">${icon('battery')}<span>Akku <strong>${s.battery} %</strong></span></div><div class="card-meta">${icon('road')}<span>Reichweite <strong>${s.range} km</strong></span></div><div class="price">0,25 € / Min.</div><p class="fee">1 € Entsperrgebühr</p><button class="${s.id===state.selected?'primary':'secondary'} card-action" data-${s.id===state.selected?'reserve':'details'}="${s.id}">${state.active?.scooterId===s.id?'Zur aktuellen Fahrt':s.id===state.selected?'Jetzt reservieren':'Details ansehen'}</button></div></article>`).join(''):`<div class="empty-list">${icon('search')}<h2>Kein Scooter gefunden</h2><p>Versuche „Mitte“, „Hauptbahnhof“ oder eine Scooter-Nummer. Der Akku-Filter zeigt nur Scooter ab 80 %.</p><button class="secondary" data-reset-filters>Filter zurücksetzen</button></div>`;
$('#availability-count').textContent=`${list.length} Scooter ${state.query||state.high?'gefunden':'in deiner Nähe'}`;$('#near-filter').classList.toggle('active',state.near);$('#near-filter').setAttribute('aria-pressed',state.near);$('#battery-filter').classList.toggle('active',state.high);$('#battery-filter').setAttribute('aria-pressed',state.high);renderMap();}
function select(id,scroll=false){if(!scooter(id))return;state.selected=id;renderList();if(cityMap&&!scroll)cityMap.panTo(COORDS[id]);if(scroll)document.querySelector(`[data-card="${id}"]`)?.scrollIntoView({block:'nearest',behavior:'smooth'});}
function changeView(view){if(!['find','rides','help'].includes(view))return;state.view=view;['find','rides','help'].forEach(v=>$(`#${v}-view`).hidden=v!==view);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(view==='rides')renderRides();if(view==='find'&&cityMap)setTimeout(()=>cityMap.invalidateSize(),20);window.scrollTo(0,0);}
function openModal(content){$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function product(s){return `<div class="modal-product"><img src="assets/scooter.webp" alt="E-Scooter ${s.id}"><div><h2 id="modal-title">Scooter ${s.id}</h2><div class="card-meta">${icon('pin')}<span>${s.place}</span></div><div class="card-meta battery">${icon('battery')}<span>${s.battery} % Akku · ${s.range} km</span></div><div class="card-meta">${icon('walk')}<span>ca. ${s.walk} Min. zu Fuß</span></div></div></div>`;}
function showDetails(id){const s=scooter(id);if(!s)return;select(id);openModal(`${product(s)}<div class="costs"><div class="cost-row"><span>Entsperren</span><strong>1,00 €</strong></div><div class="cost-row"><span>Je angefangener Minute</span><strong>0,25 €</strong></div><div class="cost-row"><span>Beispiel: 10 Minuten fahren</span><strong>3,50 €</strong></div></div><p class="modal-copy">Ein Scooter in deiner Nähe, bereit für deine nächste Demo-Fahrt.</p><button class="primary modal-full" data-reserve="${s.id}">Jetzt reservieren</button><p class="modal-note">Demo mit Beispieldaten. Keine Zahlung, keine echte Fahrzeugmiete.</p>`);}
function showReservation(id){expireReservation();const s=scooter(id);if(!s)return;if(state.active){closeModal();changeView('rides');if(state.active.scooterId!==id)toast('Beende zuerst deine aktuelle Fahrt oder Reservierung.');return;}select(id);openModal(`${product(s)}<div class="costs"><div class="cost-row"><span>10 Minuten reservieren</span><strong>Kostenlos</strong></div><div class="cost-row"><span>Entsperren bei Fahrtbeginn</span><strong>1,00 €</strong></div><div class="cost-row"><span>Je angefangener Minute</span><strong>0,25 €</strong></div></div><p class="modal-copy">Dein Scooter wartet 10 Minuten auf dich. Die Demo-Fahrt kannst du anschließend unter „Meine Fahrten“ starten.</p><button class="primary modal-full" data-confirm-reserve="${s.id}">Kostenlos reservieren</button><p class="modal-note">Du reservierst einen Demo-Scooter. Es entstehen keine Kosten und es wird kein echtes Fahrzeug gebucht.</p>`);}
function reserve(id){if(state.active)return;const s=scooter(id);if(!s)throw new Error('Unbekannter Scooter');const now=Date.now();state.active={scooterId:id,status:'reserved',created:now,expires:now+600000};persist();updateBadge();openModal(`<div class="success-icon">${icon('check')}</div><h2 id="modal-title">Dein Scooter ist reserviert.</h2><p class="modal-copy">Scooter ${id} wartet am Standort ${s.place} auf dich. Deine kostenlose Demo-Reservierung gilt für 10 Minuten.</p><button class="primary modal-full" data-show-rides>Zu meiner Reservierung</button><p class="modal-note">Unverbindliche Demo · Keine echte Fahrzeugreservierung</p>`);renderList();}
function expireReservation(){if(state.active?.status==='reserved'&&state.active.expires<=Date.now()){state.active=null;persist();updateBadge();if(state.view==='rides')renderRides();renderList();toast('Deine Reservierung ist abgelaufen. Wähle einfach wieder einen Scooter.');return true;}return false;}
function startRide(){if(expireReservation()||state.active?.status!=='reserved')return;state.active.status='riding';state.active.started=Date.now();persist();renderRides();toast('Deine Demo-Fahrt läuft. Gute Fahrt!');}
function cost(){return 1+Math.max(1,Math.ceil((Date.now()-state.active.started)/60000))*.25;}
function endRideDialog(){if(state.active?.status!=='riding')return;const s=scooter(state.active.scooterId);openModal(`<h2 id="modal-title">Demo-Fahrt beenden?</h2><p class="modal-copy">Stelle dir vor, Scooter ${s.id} steht sicher am Ziel. Du kannst die Fahrt jetzt abschließen.</p><div class="costs"><div class="cost-row"><span>Bisherige Fahrtdauer</span><strong data-live-duration>${time(Date.now()-state.active.started)}</strong></div><div class="cost-row"><span>Aktueller Demo-Preis</span><strong data-live-cost>${money(cost())}</strong></div></div><button class="primary modal-full" data-finish-ride>Fahrt beenden</button><button class="secondary modal-full" data-close>Weiterfahren</button><p class="modal-note">1 € plus 0,25 € je angefangener Minute. Der Preis wird beim Beenden berechnet. Es wird nichts abgebucht.</p>`);}
function finishRide(){if(state.active?.status!=='riding')return;const total=cost(),ended=Date.now(),id=state.active.scooterId;state.history.unshift({scooterId:id,started:state.active.started,ended,duration:ended-state.active.started,total});state.history=state.history.slice(0,100);state.active=null;persist();updateBadge();renderList();renderRides();openModal(`<div class="success-icon">${icon('check')}</div><h2 id="modal-title">Gut angekommen.</h2><p class="modal-copy">Deine Demo-Fahrt mit Scooter ${id} ist beendet. Du findest sie in deiner Fahrtübersicht.</p><div class="costs"><div class="cost-row"><span>Demo-Gesamtpreis</span><strong>${money(total)}</strong></div><div class="cost-row"><span>Tatsächlich berechnet</span><strong>0,00 €</strong></div></div><button class="primary modal-full" data-close>Alles klar</button>`);}
function cancelReservation(){if(state.active?.status!=='reserved')return;state.active=null;persist();updateBadge();renderList();renderRides();toast('Reservierung kostenlos storniert.');}
function updateBadge(){$('#ride-badge').hidden=!state.active;}
function renderRides(){const a=state.active,s=a?scooter(a.scooterId):null;let html='';if(a&&s){html=`<article class="ride-card"><img src="assets/scooter.webp" alt="Scooter ${s.id}"><div class="ride-main"><span class="status-tag">${a.status==='reserved'?'Für dich reserviert':'Demo-Fahrt läuft'}</span><h2>Scooter ${s.id}</h2><p>${s.place}</p><div class="live-time" data-live-${a.status==='reserved'?'reservation':'duration'}>${time(a.status==='reserved'?a.expires-Date.now():Date.now()-a.started)}</div><p>${a.status==='reserved'?'Zeit, um deine Demo-Fahrt zu starten':`Aktueller Demo-Preis: <strong data-live-cost>${money(cost())}</strong>`}</p></div><div class="ride-actions">${a.status==='reserved'?'<button class="primary" data-start-ride>Demo-Fahrt starten</button><button class="text-button" data-cancel-reservation>Stornieren</button>':'<button class="primary" data-end-ride>Fahrt beenden</button>'}</div></article>`;}else if(!state.history.length){html=`<div class="empty-rides">${icon('scooter')}<h2>Deine erste Fahrt wartet.</h2><p>Finde einen Scooter in Berlin und probiere<br>eine unverbindliche Demo-Fahrt aus.</p><button class="primary" data-go-find>Scooter finden</button></div>`;}else{html='<div class="local-note">Aktuell hast du keine laufende Fahrt oder Reservierung.</div>';}
if(state.history.length)html+='<h2 class="history-title">Vergangene Fahrten</h2>'+state.history.map(r=>`<article class="history-item"><div><h3>Scooter ${r.scooterId}</h3><p>${new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(r.ended))} · ${time(r.duration)} Min.</p></div><div><strong>${money(r.total)}</strong><p>Demo-Preis</p></div></article>`).join('');$('#rides-content').innerHTML=html;}
function showProfile(){openModal(`<h2 id="modal-title">Mein Profil</h2><div class="profile-card"><span class="avatar">M</span><div><h3>Demo-Gast</h3><p>Entdecke Berlin auf zwei Rädern.</p></div></div><p class="modal-copy">Du nutzt die Anwendung ohne Konto. Deine Reservierungen und Fahrten werden ausschließlich in diesem Browser gespeichert.</p><div class="costs"><div class="cost-row"><span>Abgeschlossene Demo-Fahrten</span><strong>${state.history.length}</strong></div><div class="cost-row"><span>Zahlungsmittel</span><strong>Nicht erforderlich</strong></div><div class="cost-row"><span>Speicherung im Browser</span><strong>${storageAvailable?'Aktiv':'Nicht verfügbar'}</strong></div></div><button class="secondary modal-full danger" data-reset-demo>Demo-Daten zurücksetzen</button>`);}
function resetDialog(){openModal(`<h2 id="modal-title">Demo-Daten zurücksetzen?</h2><p class="modal-copy">Alle gespeicherten Demo-Fahrten und eine laufende Reservierung oder Fahrt werden aus diesem Browser entfernt.</p><button class="primary modal-full" data-confirm-reset>Ja, Demo-Daten löschen</button><button class="secondary modal-full" data-close>Abbrechen</button>`);}
function resetFilters(){state.query='';state.high=false;state.near=true;$('#search').value='';renderList();}
function drawGeography(){
 if(typeof L==='undefined'){$('#leaflet-map').innerHTML='<div class="map-error">Die Karte konnte nicht geladen werden. Du kannst alle Scooter in der Liste auswählen.</div>';return;}
 cityMap=L.map('leaflet-map',{zoomControl:false,attributionControl:true,minZoom:14,maxZoom:16,zoomSnap:.5,zoomDelta:.5,maxBounds:[[52.496,13.343],[52.549,13.435]],maxBoundsViscosity:1}).setView([52.5187,13.3864],14.5);
 L.tileLayer('assets/tiles/{x}-{y}.png',{minNativeZoom:14,maxNativeZoom:14,minZoom:14,maxZoom:16,bounds:[[52.479,13.30],[52.57,13.49]],noWrap:true,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> &copy; <a href="https://carto.com/attributions" target="_blank" rel="noopener">CARTO</a>'}).addTo(cityMap);
 cityMap.attributionControl.setPrefix(false);
 markerLayer=L.layerGroup().addTo(cityMap);routeLayer=L.layerGroup().addTo(cityMap);
 L.circleMarker(USER_LOCATION,{radius:23,weight:0,fillColor:'#2189f4',fillOpacity:.13,interactive:false}).addTo(cityMap);
 L.circleMarker(USER_LOCATION,{radius:10,weight:4,color:'#fff',fillColor:'#1687ed',fillOpacity:1,interactive:false}).addTo(cityMap);
 cityMap.on('zoomend',applyTransform);L.control.scale({position:'bottomleft',imperial:false,maxWidth:90}).addTo(cityMap);$('#map-scale').hidden=true;
}
function renderMap(){const list=filtered(),selected=scooter();
 if(cityMap){markerLayer.clearLayers();routeLayer.clearLayers();list.forEach(s=>{const active=s.id===state.selected;const pin=L.divIcon({className:'scooter-map-marker',html:`<span class="real-pin ${active?'selected':''}">${icon('scooter')}</span>`,iconSize:[44,52],iconAnchor:[22,52]});const marker=L.marker(COORDS[s.id],{icon:pin,title:`Scooter ${s.id} · ${s.battery} % Akku`,alt:`Scooter ${s.id}, ${s.walk} Minuten entfernt`,keyboard:true,zIndexOffset:active?100:0}).addTo(markerLayer);marker.on('click',()=>select(s.id,true));});
 if(selected){L.polyline([USER_LOCATION,COORDS[selected.id]],{color:'white',weight:7,interactive:false}).addTo(routeLayer);L.polyline([USER_LOCATION,COORDS[selected.id]],{color:'#268bf3',weight:4,dashArray:'1 10',lineCap:'round',interactive:false}).addTo(routeLayer);}
 }
 $('#map-selection').hidden=!selected;if(selected)$('#map-selection').innerHTML=`${icon('walk')}<strong>ca. ${selected.walk} Min.</strong><span>zu Scooter ${selected.id}</span><button class="map-book" data-reserve="${selected.id}">Reservieren</button>`;applyTransform();
}
function applyTransform(){if(!cityMap)return;$('#zoom-in').disabled=cityMap.getZoom()>=16;$('#zoom-out').disabled=cityMap.getZoom()<=14;}
function zoom(delta){if(cityMap)cityMap.setZoom(cityMap.getZoom()+(delta>0?.5:-.5));}
function resetMap(){if(cityMap)cityMap.setView([52.5187,13.3864],14.5);toast('Karte auf den Demo-Standort in Berlin zentriert.');}
function toggleMobileMap(){state.mobileMap=!state.mobileMap;$('.map-section').classList.toggle('map-mobile',state.mobileMap);$('#mobile-toggle').textContent=state.mobileMap?'Liste anzeigen':'Karte anzeigen';$('#mobile-toggle').setAttribute('aria-expanded',state.mobileMap);if(cityMap)setTimeout(()=>cityMap.invalidateSize(),20);}
document.addEventListener('click',event=>{const t=event.target.closest('button,a,[data-select]');if(!t)return;if(t.matches('.brand')){event.preventDefault();changeView('find');}else if(t.dataset.view)changeView(t.dataset.view);else if(t.hasAttribute('data-go-find')){closeModal();changeView('find');}else if(t.dataset.select)select(t.dataset.select);else if(t.dataset.reserve)showReservation(t.dataset.reserve);else if(t.dataset.details)showDetails(t.dataset.details);else if(t.dataset.confirmReserve)reserve(t.dataset.confirmReserve);else if(t.hasAttribute('data-close'))closeModal();else if(t.hasAttribute('data-show-rides')){closeModal();changeView('rides');}else if(t.hasAttribute('data-start-ride'))startRide();else if(t.hasAttribute('data-end-ride'))endRideDialog();else if(t.hasAttribute('data-finish-ride'))finishRide();else if(t.hasAttribute('data-cancel-reservation'))cancelReservation();else if(t.hasAttribute('data-reset-filters'))resetFilters();else if(t.hasAttribute('data-reset-demo'))resetDialog();else if(t.hasAttribute('data-confirm-reset')){state.active=null;state.history=[];persist();updateBadge();renderList();renderRides();closeModal();toast('Deine Demo-Daten wurden gelöscht.');}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;renderList();});$('#near-filter').addEventListener('click',()=>{state.near=!state.near;renderList();});$('#battery-filter').addEventListener('click',()=>{state.high=!state.high;renderList();});$('#profile-button').addEventListener('click',showProfile);$('#modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});$('#zoom-in').addEventListener('click',()=>zoom(.25));$('#zoom-out').addEventListener('click',()=>zoom(-.25));$('#locate').addEventListener('click',resetMap);$('#mobile-toggle').addEventListener('click',toggleMobileMap);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();changeView('find');$('#search').focus();}});
function tick(){if(expireReservation())return;const a=state.active;if(!a)return;if(a.status==='reserved')document.querySelectorAll('[data-live-reservation]').forEach(el=>el.textContent=time(a.expires-Date.now()));else{document.querySelectorAll('[data-live-duration]').forEach(el=>el.textContent=time(Date.now()-a.started));document.querySelectorAll('[data-live-cost]').forEach(el=>el.textContent=money(cost()));}}
drawGeography();renderList();updateBadge();expireReservation();setInterval(tick,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
// Expose the same search and reservation staging actions to supported agent browsers.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'find_demo_scooters',title:'Demo-Scooter finden',description:'Filtert die sichtbare Berliner Demo-Flotte nach Ort, Scooter-Nummer und optional mindestens 80 Prozent Akku. Keine Buchung.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100},highBattery:{type:'boolean'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['query','highBattery'].includes(k))||(input.query!==undefined&&(typeof input.query!=='string'||input.query.length>100))||(input.highBattery!==undefined&&typeof input.highBattery!=='boolean'))throw new Error('Ungültige Filter');state.query=input.query||'';state.high=input.highBattery||false;$('#search').value=state.query;changeView('find');renderList();return {scooters:filtered().map(({id,battery,range,place,walk})=>({id,battery,range,place,walk})),demo:true};}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
